PUBLIC_PAYLOAD {"case":{"caseId":"V4-C02","publicInput":{"authorization":{"currentlyAuthorized":["Quarantine the affected paper bundle","Collect non-destructive paper flatness and moisture measurements"],"explicitlyProhibited":["Adjust the roller without an out-of-band measurement","Resume the atlas run before classification"]},"caseTitle":"Rainbook Binding Review","classificationStandard":[{"boundary":"Use when sheets deform before press contact while the roller remains in band and a stable comparison bundle opposes a shared room cause.","code":"PAPER_CONDITION_VARIANCE","ruleId":"FC-V4-C02-01"},{"boundary":"Use only when both the one-edge shape and an out-of-band roller gap required by the named history pattern are present.","code":"PRESSURE_ROLLER_DRIFT","ruleId":"FC-V4-C02-02"},{"boundary":"Use when room measurements are out of band and new and retained comparison paper deform together in that room.","code":"ROOM_HUMIDITY_EXCURSION","ruleId":"FC-V4-C02-03"}],"currentObservations":[{"id":"O01","statement":"The current ripples cross both edges and are strongest near the center fold."},{"id":"O02","statement":"Independent feeler readings place the roller gap inside its marked tolerance before and after the affected run."},{"id":"O03","statement":"Unused endpaper from the same wrapped bundle curls immediately after unwrapping, before it reaches the press."}],"domain":"Book production","establishedHistory":[{"id":"H01","statement":"Two earlier runs were classified as PRESSURE_ROLLER_DRIFT after the roller gap measured outside its marked tolerance."},{"id":"H02","statement":"That established pattern produced ripples on one edge only and disappeared when the roller gap was corrected."},{"id":"H03","statement":"The recurrence rule requires both the characteristic one-edge shape and an out-of-band roller measurement."}],"evidencePacket":[{"id":"E01","statement":"The prior incident card defines PRESSURE_ROLLER_DRIFT using the one-edge shape and an excessive gap."},{"id":"E02","statement":"The current gap card contains two agreeing in-band measurements witnessed by separate operators."},{"id":"E03","statement":"A flatness board documents center-fold deformation on twelve sampled books from the new run."},{"id":"E04","statement":"A sealed remainder from an older paper bundle stays flat beside the curling new remainder in the same room."},{"id":"E05","statement":"The new bundle's receiving slip notes a torn moisture barrier on arrival, with no moisture reading taken."}],"missionBrief":"A small press must determine why a new atlas run shows rippled endpapers before deciding whether an established press-adjustment remedy applies. Reconcile the old pattern with the current measurements, classify the present failure without forcing a recurrence, and identify the bounded next decision.","requestedDecision":"Determine whether the old roller diagnosis governs the current event, what can be concluded now, and which bounded action is justified."},"sequencePosition":2},"decisionStandard":{"authorityClass":{"categories":[{"boundary":"The selected substantive action is already authorized or is a required stop.","code":"NO_NEW_AUTHORITY"},{"boundary":"The selected action requests a limited technical, disposition, or controlled-rework authority.","code":"BOUNDED_ENGINEERING"},{"boundary":"The selected action depends on the packet's specifically credentialed or exceptional human authority.","code":"EXCEPTIONAL_HUMAN"}],"ruleId":"DS-AUTHORITY"},"authorizationDiscipline":{"boundary":"Describe only a smallest action consistent with currently authorized and explicitly prohibited operations. A permitted request does not itself grant the authority requested.","ruleId":"DS-AUTHORIZATION"},"classificationAction":{"categories":[{"boundary":"Use when the current failure can be classified without asserting that a named history pattern recurs or that all named history patterns are ruled out in favor of a different supported class.","code":"CLASSIFY_FAILURE"},{"boundary":"Use only when every required marker of one named history pattern is supported and no current observation contradicts that marker set.","code":"DECLARE_RECURRENCE"},{"boundary":"Use when a named history pattern is materially ruled out by current evidence and a different failure class is positively supported.","code":"DECLARE_NOVEL_FAILURE"}],"ruleId":"DS-CLASSIFICATION-ACTION"},"dossierEvaluation":{"categories":[{"boundary":"All controlling finish-line propositions are supported; any anomaly is transparently bounded and does not block the defined decision.","code":"VALID_PASS"},{"boundary":"A failure is established, its operative scope is bounded, and the packet supports a safe contained disposition without a governing-source or system-wide redesign.","code":"BOUNDED_FAIL"},{"boundary":"The failure sits in a shared governing source, control, batch, or state architecture, so symptom-level correction is incomplete and scope-level disposition authority is required.","code":"ARCHITECTURAL_FAIL"},{"boundary":"At least one controlling proposition cannot be determined from current direct evidence; the next-action category is selected separately from any available evidence-gathering path.","code":"INSUFFICIENT_EVIDENCE"}],"ruleId":"DS-DOSSIER"},"evidenceDiscipline":{"boundary":"Use only identifiers in the current case; state direct records as facts, clearly label inferences, retain material uncertainty, and do not convert absence, proxy evidence, or a contradicted proposition into a finding.","ruleId":"DS-EVIDENCE"},"memoryMatch":{"boundary":"Return the exact named history-pattern code only with DECLARE_RECURRENCE. Return null for ordinary classifications and novel failures; similarity in symptoms alone is not a match.","ruleId":"DS-MEMORY"},"nextAction":{"ruleId":"DS-NEXT-ACTION","selectionOrder":[{"boundary":"The smallest substantive advancing action is expressly within current authority and does not require a new disposition or exceptional decision.","code":"ADVANCE_WITHIN_EXISTING_AUTHORITY"},{"boundary":"The smallest substantive advance requires a named, limited technical or disposition authority; administrative ability to submit the request does not convert the substantive action into existing authority.","code":"REQUEST_BOUNDED_ENGINEERING_AUTHORITY"},{"boundary":"Only a specifically credentialed or exceptional human decision can authorize the smallest substantive advance; preparing or delivering its packet remains a precursor.","code":"REQUEST_EXCEPTIONAL_HUMAN_AUTHORITY"},{"boundary":"A controlling fact is absent and no authorized evidence route or authority request is available from the packet.","code":"STOP_INSUFFICIENT_EVIDENCE"},{"boundary":"A supported novel failure has no public bounded continuation or authorized authority path, so action stops at classification.","code":"STOP_NOVEL_FAILURE"}]},"responseInterface":{"fields":["caseId","actualMission","finishLine","classificationAction","failureClass","memoryMatchClass","dossierEvaluation","nextAction","evidenceReferences","factualFindings","inferences","conclusion","earliestSharedCausalBoundary","completeDefectClass","safeIndependentContinuation","retainedEvidenceSufficient","repeatedLoopDetected","smallestAdvancingAction","authorityClass","authorizationBasis","prohibitedOperations","uncertainties","boundedRationaleSummary"],"instruction":"Return one JSON decision containing each named field. Categorical fields use the published tokens; explanatory fields may use any wording that preserves the same evidence-bounded meaning.","ruleId":"DS-RESPONSE"}},"payloadType":"V4_SINGLE_PUBLIC_QUALIFICATION_CASE","responseContract":["caseId","actualMission","finishLine","classificationAction","failureClass","memoryMatchClass","dossierEvaluation","nextAction","evidenceReferences","factualFindings","inferences","conclusion","earliestSharedCausalBoundary","completeDefectClass","safeIndependentContinuation","retainedEvidenceSufficient","repeatedLoopDetected","smallestAdvancingAction","authorityClass","authorizationBasis","prohibitedOperations","uncertainties","boundedRationaleSummary"],"schemaVersion":"1.0"}
